platform_topbar.css:
/* BioQuill Platform Top Bar */
.bq-topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  height: 48px;
  background-color: #F5C518;
  box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0;
}

.bq-topbar__logo-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-left: 16px;
  flex-shrink: 0;
}

.bq-topbar__circle {
  width: 56px;
  height: 56px;
  background: #1A1A1A;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  /* Overflow: circle is 56px in 48px bar = 8px overflow, split 4px top/bottom */
  margin-top: -4px;
  margin-bottom: -4px;
  overflow: visible;
}

.bq-topbar__wordmark {
  font-family: 'Inter', sans-serif;
  font-weight: 700;
  font-size: 20px;
  letter-spacing: -0.02em;
  color: #1A1A1A;
  white-space: nowrap;
}

.bq-topbar__nav {
  display: flex;
  align-items: center;
  gap: 32px;
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}

.bq-topbar__nav-link {
  font-size: 14px;
  font-weight: 500;
  color: #1A1A1A;
  text-decoration: none;
  white-space: nowrap;
  opacity: 0.85;
}

.bq-topbar__nav-link--active {
  opacity: 1;
  border-bottom: 2px solid #1A1A1A;
  padding-bottom: 2px;
}

.bq-topbar__right {
  display: flex;
  align-items: center;
  padding-right: 24px;
  flex-shrink: 0;
}

.bq-topbar__refresh-pill {
  font-size: 12px;
  color: #1A1A1A;
  background: rgba(255,255,255,0.35);
  border-radius: 20px;
  padding: 4px 12px;
  white-space: nowrap;
}

/* Push page content below fixed bar */
.bq-page-content {
  margin-top: 48px;
}

pdf_header.css_for_pdf_generator:
/* BioQuill PDF Header — inject at top of every generated PDF */
.bq-pdf-header {
  width: 100%;
  height: 42px;
  background-color: #F5C518;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
  overflow: visible;
  page-break-inside: avoid;
}

.bq-pdf-header__left {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-left: 20px;
  overflow: visible;
}

.bq-pdf-header__circle {
  width: 52px;
  height: 52px;
  background: #1A1A1A;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: -5px;
  margin-bottom: -5px;
}

.bq-pdf-header__wordmark {
  font-family: 'Inter', sans-serif;
  font-weight: 700;
  font-size: 13pt;
  color: #1A1A1A;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.bq-pdf-header__separator {
  width: 1px;
  height: 22px;
  background: rgba(26,26,26,0.25);
  margin: 0 12px;
}

.bq-pdf-header__tagline {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.bq-pdf-header__tagline span {
  font-family: 'Inter', sans-serif;
  font-size: 7.5pt;
  color: #1A1A1A;
  line-height: 1.3;
}

.bq-pdf-header__right {
  margin-left: auto;
  padding-right: 24px;
  display: flex;
  align-items: center;
}

.bq-pdf-header__refresh-pill {
  font-family: 'Inter', sans-serif;
  font-size: 7.5pt;
  color: #1A1A1A;
  background: rgba(255,255,255,0.30);
  border-radius: 8px;
  padding: 3px 10px;
  white-space: nowrap;
}
